import { after } from "next/server";

import { logPageView } from "./lib/analytics";

export default function Home() {
  after(async () => {
    try {
      await logPageView({
        path: "/",
        viewedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error("Failed to log page view", error);
    }
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting this page.</p>
    </main>
  );
}

